function hilfen(f) {
  const en = f.sprache === "en";
  return {
    ...f,
    en,
    pct: (v, s = 1) => (v == null || !Number.isFinite(v) ? "–" : f.fmtPct(v, s)),
    tsd: (v) => (en ? `${v < 0 ? "-" : ""}€${f.fmt(Math.abs(v) / 1000)}k` : `${f.fmt(v / 1000)} T€`),
    mioAchse: (v, s) => (en ? `${v < 0 ? "−" : ""}€${f.fmt(Math.abs(v) / 1e6, s)}m` : `${v < 0 ? "−" : ""}${f.fmt(Math.abs(v) / 1e6, s)} Mio.`),
  };
}

